/**
 * Centros de pupila (en el espacio interno del viewBox 400x400) por cada
 * opción de ojos que tiene pupila movible, más el radio máximo (rx/ry, en
 * las mismas unidades) que la pupila puede desplazarse desde ese centro
 * sin salirse del blanco del ojo. js/app.js los usa para el seguimiento de
 * mouse (updatePupils) según cuál ojos esté elegido.
 *
 * Antes había un único radio circular (EYE_MAX_R) para todas las opciones,
 * y en ojos-1/ojos-3 eso hacía que la pupila se saliera del blanco del ojo
 * y se viera "rota" al moverse hacia los bordes (bug reportado). Cada ojo
 * es una elipse más ancha que alta, así que rx/ry están ajustados a mano
 * (mirando capturas) por separado.
 *
 * v2.4: pedido explícito — "las pupilas deberían seguir más al mouse, que
 * deje de ser algo sutil". Antes (pedido de esa época) estos valores se
 * habían dejado chicos a propósito para que el movimiento casi no se
 * notara; ahora se agrandaron varias veces respecto a eso (más en el eje
 * horizontal, donde el blanco del ojo tiene más margen, que en el
 * vertical, más angosto) verificando visualmente que la pupila siga sin
 * cruzar el contorno negro del ojo. Si en algún momento se pide más/menos,
 * este es el lugar para tocarlo.
 */
const PET_EYE_CENTERS_BY_OJOS = {
  // v2.0: este centro/radio era el de la vieja "ojos-4" — la opción que
  // ahora ocupa el id "ojos-1" (ver comentario en PET_PARTS_MANIFEST.ojos)
  // es ese mismo dibujo, así que se reusa tal cual.
  "ojos-1": { izq: { x: 169.5, y: 163.2 }, der: { x: 230.5, y: 163.2 }, rx: 3.4, ry: 0.65 },
  "ojos-3": { izq: { x: 167.1, y: 164.0 }, der: { x: 232.1, y: 164.0 }, rx: 3.2, ry: 2.5 },
};

/**
 * v2.0 (histórico): "Jardín" y "Living" eran fondos elegibles en el
 * creador, guardados en state.scenario. v2.1: dejaron de ser una opción de
 * personalización — ahora son LUGARES navegables del juego (Casa y
 * Jardín), con puerta para ir de uno a otro (ver PET_LOCATIONS abajo,
 * normalizeLocation en js/state.js, y la lógica de navegación en
 * js/app.js). PET_SCENARIOS queda sólo como referencia histórica para
 * entender la migración de guardados viejos — el juego ya no lo usa.
 */
const PET_SCENARIOS = [
  { id: "jardin", label: "Jardín" },
  { id: "living", label: "Living" },
];

/**
 * v2.1: Casa y Jardín como lugares navegables (sección 4 del pedido). No
 * son imágenes — son fondos ilustrados con CSS puro (gradientes + formas
 * en .location-deco, ver css/style.css e index.html), fijos: no hay
 * compra/colocación/edición de muebles. El id de cada uno matchea la clase
 * CSS ".location-<id>" aplicada a #stage-floor, y es el mismo valor que se
 * guarda en state.location (ver js/state.js). "exitLabel"/"to" describen
 * la puerta/entrada de ESE lugar hacia el otro (etiqueta del hotspot +
 * destino).
 */
const PET_LOCATIONS = [
  { id: "casa", label: "Casa", exitLabel: "Salir al jardín", to: "jardin", side: "left" },
  { id: "jardin", label: "Jardín", exitLabel: "Entrar a casa", to: "casa", side: "right" },
];

function getLocationDef(id) {
  return PET_LOCATIONS.find((l) => l.id === id) || PET_LOCATIONS[0];
}

/* v2.5: fondo ilustrado real de la Casa (pedido explícito, reemplaza el
 * fondo hecho con gradientes CSS) — extraído fielmente de home-scene.ai
 * (PDF-compatible, misma técnica que logo_alpha.ai/orejas_v2.0.ai: sin
 * Illustrator, con pdftocairo + reconstrucción por color/orden de pintado)
 * y agrupado en 5 capas con el mismo nombre y el mismo orden de apilado
 * que tenía el archivo original (verificado: el primer trazo pintado es
 * el piso, el último es la alfombra — exactamente "abajo de todo suelo,
 * arriba de todo alfombra", pedido explícito):
 *   scene-suelo (piso de madera) < scene-pared (pared + zócalo de
 *   paneles) < scene-ventana (marco + vidrio) < scene-puerta (puerta +
 *   picaporte) < scene-alfombra (alfombra a los pies de la puerta).
 * Va pegado como texto (igual criterio que el resto del arte que necesita
 * que JS/CSS lo toquen): el vidrio de la ventana tiene id="fondo-cambiable"
 * (mismo nombre de capa que en el .ai) con fill="var(--ventana-color,
 * #cdeaf6)" — #cdeaf6 es el color EXACTO del archivo original, así que de
 * día se ve igual que siempre y de noche css/style.css sólo pisa esa
 * variable (.stage-floor.location-casa.is-night). La puerta
 * (#scene-puerta) es clickeable — pedido explícito, "que funcione como
 * hacerle click al botón Salir al jardín" — ver setupNavigation() en
 * js/app.js, que delega el click sobre #location-deco. */
