/**
 * Color de ojos (pedido explícito) — swatches de color de verdad, igual
 * mecanismo que bodyColor. Se aplica a través de --eye-color (ver
 * renderPetLayers en js/app.js) sobre los elementos con clase
 * "iris-main"/"iris-shadow" del ojo elegido (ver css/style.css) — el color
 * "shadow" no se guarda aparte, sale de mezclar el principal con negro
 * (color-mix en CSS), así no hace falta duplicar cada opción.
 *
 * OJO: sólo afecta a las opciones de ojos CON pupila separada (ojos-1,
 * ojos-3 — las que tienen movable:true). ojos-2 es una forma de
 * un solo color sin pupila aparte (ver comentario en PET_PARTS_MANIFEST),
 * así que no tiene un "iris" que recolorear — se queda con su color fijo
 * elija el que elija acá. No es un bug, es una limitación de ese arte en
 * particular; si en algún momento se rehace ojos-2 con una pupila
 * separada, se le pueden agregar las mismas clases y empieza a responder
 * solo, sin tocar esta lista.
 *
 * El primero (Gris) es a propósito el mismo tono que ya tenía ojos-1 por
 * defecto, para que una mascota ya creada no cambie de aspecto de golpe
 * apenas se actualiza la app.
 */
const PET_EYE_COLORS = [
  { id: "gris", label: "Gris", swatch: "#4c4c4c" },
  { id: "cafe", label: "Café", swatch: "#6d4a1f" },
  { id: "miel", label: "Miel", swatch: "#a9762f" },
  { id: "verde", label: "Verde", swatch: "#5d8a5a" },
  { id: "azul", label: "Azul grisáceo", swatch: "#5f7e94" },
  { id: "violeta", label: "Violeta", swatch: "#74507f" },
];

/**
 * Torso/cuerpo: sale de tu archivo cuerpo_v1.0.ai (un trapecio simple, sin
 * mesa de trabajo compartida con los 6 archivos de cara — tiene su propia
 * escala). Lo reposicioné/escalé a mano para que calce entre el mentón de
 * la cabeza y donde arrancan las piernas (mismo método visual que usé para
 * alinear cabeza/orejas/ojos/nariz/boca/cejas la primera vez). Toma el
 * color elegido igual que cabeza/orejas/brazos/piernas (class="cuerpo-base")
 * — tu archivo no tenía contorno propio, así que le agregué el mismo trazo
 * sutil al 6% que ya usan cabeza/orejas/brazos/piernas, para que no
 * desentone. Se dibuja después de las piernas y antes de las orejas, así
 * tapa el arranque de las piernas (quedan como si salieran de abajo del
 * cuerpo) y brazos/cabeza lo tapan a su vez por arriba/costados.
 */
const PET_TORSO_INLINE = `
  <path d="M 160.14,185 L 238.86,185 L 250.42,275 L 148.58,275 Z" class="cuerpo-base" fill="#6fb8e0" stroke="#000000" stroke-opacity="0.06" stroke-width="6"/>
  <ellipse cx="199.1" cy="234.4" rx="20.4" ry="26.0" fill="#ffffff" fill-opacity="0.08"/>`;

/* La elipse de arriba es tu edición v1.1 del torso (cuerpo_v1.1.ai): un
 * brillito blanco suave para la panza. No lleva "cuerpo-base" porque va
 * siempre blanca, sin importar el color de cuerpo elegido — encima del
 * trapecio, sin contorno. La opacidad no viene declarada como 0.08 en el
 * PDF crudo (ahí el blanco figura al 100%, como pasaba con el contorno de
 * cabeza/orejas): la muestreé yo mismo renderizando el archivo y comparando
 * el color resultante contra el celeste de base, y me dio ~0.076–0.094
 * según el canal — 0.08 es el punto medio, así que la dejé en ese valor. */

/* stroke con la misma opacidad 0.06 que cabeza/orejas/torso: sin esto, un
 * brazo/pierna del mismo color que el torso que tienen detrás se vuelve
 * invisible donde se superponen (mismo color sobre mismo color, sin borde
 * que los separe) — con el trazo sutil, el límite del brazo/pierna se ve
 * aunque esté "adentro" del torso, como una costura suave. */
